SELECT ?actor WHERE {
  ?show wdt:P31 wd:Q5398426;         # TV show
        rdfs:label "A Lua Me Disse"@en;
        wdt:P161 ?actor.             # cast member
  ?actor wdt:P166 ?awardStatement.
  ?awardStatement ps:P166 wd:Q18545; # Golden Globe Award
                  pq:P1686 ?nomination. # nomination status
  ?nomination rdfs:label ?nominationLabel.
  FILTER(CONTAINS(LCASE(?nominationLabel), "nomination")).
  ?role wdt:P1346 ?actor;
        rdfs:label ?roleName.
  FILTER(CONTAINS(LCASE(?roleName), "king of cocaine")).
} LIMIT 10

