SELECT ?director ?directorName WHERE {
  ?film rdfs:label "Boxing Helena"@en ;
        dbo:director ?director ;
        dbo:classification ?classification .
  FILTER(CONTAINS(LCASE(STR(?classification)), "15"))
  ?director dbo:occupation dbo:FilmDirector .
  ?director rdfs:label ?directorName .
  FILTER(LANG(?directorName) = "en")
}

